// Skript: Frist_berechnen - berechnet ein Fälligkeitsdatum in Werktagen (Mo-Fr, ohne Feiertage, UTC)
// Variablen: keine
// Authentifizierung: keine (keine externen Aufrufe)
const MAX_WERKTAGE = 3650;

module.exports = async (req, res) => {
  try {
    let body;
    try {
      body = req.text() ? JSON.parse(req.text()) : {};
    } catch {
      res.status(400).json({ error: "Request-Body ist kein gültiges JSON." });
      return;
    }

    const { startDatum, werktage } = body?.input ?? {};
    const tage = parseWerktage(werktage);
    if (tage === null) {
      res.status(400).json({ error: `input.werktage (ganze Zahl von 0 bis ${MAX_WERKTAGE}) ist erforderlich.` });
      return;
    }

    const start = startDatum ? new Date(startDatum) : new Date();
    if (Number.isNaN(start.getTime())) {
      res.status(400).json({ error: "input.startDatum ist kein gültiges ISO-8601-Datum." });
      return;
    }

    const frist = new Date(start);
    let rest = tage;
    while (rest > 0) {
      frist.setUTCDate(frist.getUTCDate() + 1);
      const wochentag = frist.getUTCDay();
      if (wochentag !== 0 && wochentag !== 6) rest--;
    }

    res.status(200).json({ output: { fristDatum: frist.toISOString() } });
  } catch (err) {
    console.error("Fristberechnung fehlgeschlagen:", err.message);
    res.status(500).json({ error: "Interner Fehler bei der Fristberechnung." });
  }
};

function parseWerktage(value) {
  const isNumeric = typeof value === "number" || (typeof value === "string" && value.trim() !== "");
  const n = isNumeric ? Number(value) : NaN;
  return Number.isInteger(n) && n >= 0 && n <= MAX_WERKTAGE ? n : null;
}
